import { IHotel } from '@hotel-booking-platform/shared-types/src/domain/hotel';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useEffect, useState } from 'react';
import {
    ActivityIndicator,
    Dimensions,
    FlatList,
    Image,
    SafeAreaView,
    StatusBar, // 确保引入 StyleSheet
    Text,
    TextInput,
    TouchableOpacity,
    TouchableWithoutFeedback,
    View
} from 'react-native';
import { RootStackParamList } from '../../navigation/types';

import { styles } from './index.styles';

const { width, height } = Dimensions.get('window');

type Props = NativeStackScreenProps<RootStackParamList, 'HotelList'>;

// 1. 定义筛选数据结构
const SORT_OPTIONS = [
    { label: '欢迎度排序', value: 'popular' },
    { label: '好评优先', value: 'score_desc' },
    { label: '低价优先', value: 'price_asc' },
    { label: '高价优先', value: 'price_desc' },
    { label: '距离优先', value: 'distance_asc' },
];

const HotelListScreen = ({ route, navigation }: Props) => {
    // 获取首页传递的参数
    const { city = '', startDate = '', endDate = '', name = '', brand = '' } = route.params || {};

    const handleDateChange = (Date: string) => {
        return Date.split('-').slice(1).join('-');
    }

    const newStartDate = handleDateChange(startDate);
    const newEndDate = handleDateChange(endDate);

    const [hotels, setHotels] = useState<IHotel[]>([]);
    const [loading, setLoading] = useState(false);

    // --- 筛选相关的状态 ---
    // 当前激活的Tab索引，null表示未展开
    const [activeTab, setActiveTab] = useState<number | null>(null);
    // 当前选中的排序值
    const [selectedSort, setSelectedSort] = useState('popular');
    // 获取排序显示的文本
    const currentSortLabel = SORT_OPTIONS.find(o => o.value === selectedSort)?.label || '欢迎度排序';

    // 模拟数据加载
    const loadData = (isRefresh = false) => {
        if (loading) return;
        setLoading(true);

        setTimeout(() => {
            const mockData: IHotel[] = Array.from({ length: 5 }).map((_, i) => ({
                id: Math.random().toString(),
                name: `嘉豪酒店 ${isRefresh ? i + 1 : hotels.length + i + 1}号店`,
                image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=400&q=80',
                score: 4.8,
                comments: 1200,
                address: '海淀区中关村大街15号 | 距您直线2.3km',
                tags: ['免费停车', '极速WiFi', '欢迎水果'],
                price: 588 + (isRefresh ? i : hotels.length + i) * 10,
            }));

            setHotels(prev => isRefresh ? mockData : [...prev, ...mockData]);
            setLoading(false);
        }, 800);
    };

    useEffect(() => {
        loadData(true);
    }, []);

    // --- 处理筛选点击 ---
    const toggleFilterTab = (index: number) => {
        if (activeTab === index) {
            setActiveTab(null); // 关闭
        } else {
            setActiveTab(index); // 打开
        }
    };

    const handleSortSelect = (value: string) => {
        setSelectedSort(value);
        setActiveTab(null); // 选择后关闭菜单
        // 这里可以触发重新加载数据 loadData(true)
        console.log('Selected sort:', value);
    };

    // --- 渲染下拉菜单内容 ---
    const renderDropdownContent = () => {
        if (activeTab === null) return null;

        // 仅演示第一个Tab（排序）的内容，其他Tab可以类似扩展
        let content = null;
        if (activeTab === 0) {
            content = (
                <View style={styles.dropdownList}>
                    {SORT_OPTIONS.map((option) => (
                        <TouchableOpacity
                            key={option.value}
                            style={styles.dropdownItem}
                            onPress={() => handleSortSelect(option.value)}
                        >
                            <Text style={[
                                styles.dropdownItemText,
                                selectedSort === option.value && styles.activeDropdownItemText
                            ]}>
                                {option.label}
                            </Text>
                            {selectedSort === option.value && (
                                <Text style={styles.checkIcon}>✓</Text>
                            )}
                        </TouchableOpacity>
                    ))}
                </View>
            );
        } else {
            // 其他Tab的占位内容
            content = (
                <View style={styles.dropdownList}>
                    <View style={{ padding: 20, alignItems: 'center' }}>
                        <Text style={{ color: '#999' }}>更多筛选功能开发中...</Text>
                    </View>
                </View>
            );
        }

        return (
            <View style={styles.dropdownContainer}>
                {/* 蒙层 - 点击关闭 */}
                <TouchableWithoutFeedback onPress={() => setActiveTab(null)}>
                    <View style={styles.mask} />
                </TouchableWithoutFeedback>

                {/* 下拉列表主体 */}
                <View style={styles.dropdownContent}>
                    {content}
                </View>
            </View>
        );
    };

    const renderHotelItem = ({ item }: { item: IHotel }) => (
        <TouchableOpacity
            activeOpacity={0.9}
            style={styles.hotelItem}
            onPress={() => navigation.navigate('HotelDetail', { hotelId: item.id, hotelName: item.name })}
        >
            <Image source={{ uri: item.image }} style={styles.hotelImage} />
            <View style={styles.infoArea}>
                <View>
                    <Text style={styles.hotelName} numberOfLines={1}>{item.name}</Text>
                    <View style={styles.scoreRow}>
                        <Text style={styles.scoreText}>{item.score}分</Text>
                        <Text style={styles.commentText}>{item.comments}评价</Text>
                    </View>
                    <Text style={styles.addressText} numberOfLines={1}>{item.address}</Text>
                    <View style={styles.tagRow}>
                        {item.tags.map((tag, idx) => (
                            <View key={idx} style={styles.hotelTag}>
                                <Text style={styles.hotelTagText}>{tag}</Text>
                            </View>
                        ))}
                    </View>
                </View>
                <View style={styles.priceContainer}>
                    <Text style={styles.priceSymbol}>¥</Text>
                    <Text style={styles.priceText}>{item.price}</Text>
                    <Text style={styles.priceUnit}>起</Text>
                </View>
            </View>
        </TouchableOpacity>
    );

    const filterTabs = [
        { label: currentSortLabel, index: 0 },
        { label: '位置距离', index: 1 },
        { label: '价格/星级', index: 2 },
        { label: '筛选', index: 3 },
    ];

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" backgroundColor="#fff" />

            {/* 1. 顶部自定义搜索头 (zIndex需要设置高一点，保证下拉菜单盖住列表) */}
            <View style={[styles.headerContainer, { zIndex: 10 }]}>
                <View style={styles.searchBarContainer}>
                    {/* 返回按钮 */}
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <Text style={styles.backIcon}>{'<'}</Text>
                    </TouchableOpacity>

                    {/* 搜索框主体 */}
                    <View style={styles.searchMainContent}>
                        <Text style={styles.cityText}>{city || '上海'}</Text>
                        <View style={styles.dateVerticalContainer}>
                            <View style={styles.dateRow}>
                                <Text style={styles.dateLabel}>住</Text>
                                <Text style={styles.dateValue}>{newStartDate || '01-09'}</Text>
                            </View>
                            <View style={styles.dateRow}>
                                <Text style={styles.dateLabel}>离</Text>
                                <Text style={styles.dateValue}>{newEndDate || '01-10'}</Text>
                            </View>
                        </View>
                        <Text style={styles.nightCountText}>1晚</Text>
                        <View style={styles.verticalDivider} />
                        <View style={styles.keywordContainer}>
                            <Text
                                style={styles.searchIcon}
                                onPress={() => navigation.navigate('HotelList', {
                                    city, brand, name,
                                    startDate, endDate,
                                })}
                            >🔍</Text>
                            <TextInput
                                style={styles.keywordPlaceholder}
                                placeholderTextColor="#ccc"
                                placeholder="位置/品牌/酒店"
                            />
                        </View>
                    </View>
                </View>

                {/* 2. 筛选Tab栏 */}
                <View style={styles.filterRow}>
                    {filterTabs.map((item) => {
                        const isActive = activeTab === item.index;
                        const isSelected = item.index === 0 ? true : false; // 示例：仅第一个展示选中态逻辑

                        return (
                            <TouchableOpacity
                                key={item.index}
                                style={styles.filterItem}
                                onPress={() => toggleFilterTab(item.index)}
                            >
                                <Text style={[
                                    styles.filterText,
                                    (isActive || (item.index === 0 && selectedSort !== 'popular')) && styles.activeFilterText
                                ]}>
                                    {item.label}
                                </Text>
                                <Text style={[
                                    styles.arrowIcon,
                                    isActive && styles.activeArrowIcon
                                ]}>
                                    {isActive ? '▲' : '▼'}
                                </Text>
                            </TouchableOpacity>
                        );
                    })}
                </View>

                {/* 下拉菜单 (绝对定位在 Header 内部) */}
                {renderDropdownContent()}
            </View>

            {/* 3. 酒店列表 */}
            <FlatList
                data={hotels}
                renderItem={renderHotelItem}
                keyExtractor={item => item.id}
                onEndReached={() => loadData()}
                onEndReachedThreshold={0.2}
                showsVerticalScrollIndicator={false}
                ListFooterComponent={
                    loading ? (
                        <View style={styles.footerLoading}>
                            <ActivityIndicator color="#007AFF" />
                        </View>
                    ) : <View style={{ height: 20 }} />
                }
            />
        </SafeAreaView>
    );
};
export default HotelListScreen;
